                                const std::uint8_t subsub_step,
                                const std::uint8_t subsubsub_step) noexcept {
    // Native case 3: files/models are already loaded. Open Stage start
    // (subsub==0) is too early — pumping G07 there AVs and blacks the frame.
    return state == 3 && substep == 3 && subsub_step == 1 &&
           subsubsub_step == 3;
}

