std::uint8_t battle_rng_draw(RngState& state) noexcept {
    const std::uint8_t lane = static_cast<std::uint8_t>(state.active_lane & 7u);
    const std::uint8_t index = state.lane_index[lane];
    ++state.lane_index[lane];
    return kBattleRandomTable[index];
}

void battle_rng_seed(RngState& state, std::uint8_t seed) noexcept {
    for (std::uint8_t lane = 0; lane < state.lane_index.size(); ++lane) {
        state.lane_index[lane] = seed;
        const std::uint8_t index = state.lane_index[0];
        ++state.lane_index[0];
        seed = kBattleRandomTable[index];
    }
    const std::uint8_t index = state.lane_index[0];
    ++state.lane_index[0];
    state.active_lane = static_cast<std::uint8_t>(kBattleRandomTable[index] & 7u);
}

std::uint8_t battle_rng_seed_from_holdrand(RngState& state, std::uint32_t& holdrand) noexcept {
    holdrand = holdrand * 214013u + 2531011u;
    const std::uint8_t seed = static_cast<std::uint8_t>((holdrand >> 16u) & 0x7fffu);
    battle_rng_seed(state, seed);
    return seed;
}

bool battle_rng_roll_num_den_255(RngState& state, const std::uint32_t numerator,
                                 const std::uint32_t denominator) noexcept {
    if (denominator == 0) {
        return false;
    }
    const std::uint32_t threshold = static_cast<std::uint32_t>(
        (static_cast<std::uint64_t>(255u) * numerator) / denominator);
    return threshold != 0 && threshold >= battle_rng_draw(state);
}

